{
  "description": "The creature is shown in right-facing side profile as a low, quadrupedal animal with a stout, elongated body. Its head is broad, flat and blunt-snouted with large golden eyes and pale pink-tan skin speckled with dark spots on the crown, and multiple feathery pinkish-red external gills project from the neck just behind the head on both sides. The entire dorsal surface from the back of the neck to the base of the tail and down the sides is covered in overlapping large brown keratinous scales with darker edges and lighter centers arranged in diagonal rows, while the ventral surface, throat, head, legs and tail are covered in pale pink, deeply wrinkled fleshy skin. It stands on four short, thick, splayed limbs each ending in a broad five-toed foot with small claws, and a thick, tapering, wrinkled tail extends posteriorly from the body, partially visible at the left edge of the image.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and blunt-snouted with a slightly upturned mouth, pale pink-tan skin with irregular dark brown speckling on the dorsal crown, large round golden-yellow eyes with black pupils on the sides, and small round nostrils at the tip of the snout",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "eyes",
      "looks_like": "large, prominent and round with golden-yellow irises and large black pupils, glossy",
      "where": "on the dorsolateral sides of the head, one clearly visible on the near side"
    },
    {
      "part": "gills",
      "looks_like": "multiple feathery external gills, pinkish-red with a central stalk bearing fine hair-like filaments along both sides, fleshy and branched",
      "where": "projecting outward and upward from the neck region immediately behind the head on both the near and far sides, about four stalks visible on the near side and about five on the far side"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous plates, brown with darker brown-black margins and lighter tan-brown centers, with fine radial striations, arranged in neat diagonal rows",
      "where": "covering the entire dorsal surface and sides of the body from just behind the gills to the base of the tail, forming a continuous armored back"
    },
    {
      "part": "skin",
      "looks_like": "pale pink to light beige, highly wrinkled, folded and fleshy with a moist appearance, with transverse wrinkles on the belly and limbs",
      "where": "on the head, throat, ventral belly, all four limbs, and the tail where not covered by scales"
    },
    {
      "part": "legs",
      "looks_like": "four short, stout and muscular limbs with thick wrinkled skin, bent at the joints in a splayed standing posture",
      "where": "two forelimbs positioned under the chest and two hindlimbs under the mid-posterior body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, fleshy feet with five distinct toes each tipped with a small blunt claw, pale pink with wrinkled skin and splayed toes",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, fleshy and tapering to a point, covered in pale pink wrinkled skin with a small continuation of the dorsal scales at its base",
      "where": "extending posteriorly from the rear of the body to the left side of the image, partially cropped"
    },
    {
      "part": "markings",
      "looks_like": "irregular small dark brown to black speckles and mottling",
      "where": "concentrated on the dorsal surface of the head and around the eyes, fading toward the snout and cheeks"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
